"""Layouts for the eight competition slides and the team page."""
import html
from pathlib import Path

def photo(name, alt='', cls=''):
    return f'<img class="{cls}" src="assets/{name}" alt="{html.escape(alt)}">'

def bars(rows, maximum=100):
    return ''.join(f'<div class="barrow"><span>{label}</span><i><u style="width:{value/maximum*100:.2f}%;background:{color}"></u></i><b>{str(value).replace(".",",")}%</b></div>' for label,value,color in rows)

def tag(text): return f'<div class="eyebrow">{text}</div>'
def stat(n, label): return f'<div class="stat"><strong>{n}</strong><span>{label}</span></div>'
def panel(title,body,kind=''): return f'<article class="pane {kind}">{tag(title)}{body}</article>'

def cash_chart(model):
    months=[-model['investment_rub']]+[x['cumulative_cash'] for x in model['scenarios'][1]['months']]
    xy=lambda i,v:(58+i*21,105-v/100000)
    pts=' '.join('%.1f,%.1f'%xy(i,v) for i,v in enumerate(months))
    axis=''.join(f'<text x="5" y="{y+5}">{label}</text><path d="M55 {y}h508" stroke="#d8e1ec"/>' for y,label in [(55,'+5'),(105,'0'),(155,'−5')])
    return f'<svg viewBox="0 0 590 200" class="cash">{axis}<polyline fill="none" stroke="#07f" stroke-width="5" points="{pts}"/><circle cx="415" cy="{xy(17,months[17])[1]}" r="6" fill="#e33496"/><text x="350" y="75">Окупаемость</text><text x="54" y="190">Старт</text><text x="300" y="190">12 мес.</text><text x="510" y="190">24 мес.</text></svg>'

def product():
    return '<div class="productart"><div class="mug"><i></i></div></div>'

def make_pages(model):
    chart=bars([('Есть чекаут',91.9,'#07f'),('Есть заказы',7.2,'#ed389a')])
    gap=panel('Бизнесы с активным каталогом',chart+'<p>Обе доли рассчитаны от одной группы за сентябрь. Данные не показывают, на каком шаге каждый продавец потерял заказ.</p>')
    cover=photo('shapes.jpg','','sculpt')+photo('brand.jpg','VK Education и ВКонтакте','coverbrand')+'<div class="covercopy">'+tag('VK Case Champ 2026   /   Стратегия')+'<h2>Следующий<br>заказ</h2><p>Как помочь бизнес-сообществам ВКонтакте<br>продавать своей аудитории</p></div><div class="signature">Digital Cat$ <small>Москва, 2026</small></div>'
    why='<div class="twocol">'+gap+panel('Что меняем в кабинете',photo('seller.jpg','Предприниматели за работой','sellerphoto')+'<h3>От настройки магазина к первой продаже</h3><p>Кабинет помогает выбрать готовый товар, опубликовать его и проверить, выполнен ли заказ.</p>')+'</div>'+stat('+5 п.п.','целевой прирост доли бизнесов с заказом за 30 дней относительно контроля')
    segments='<div class="twocol">'+panel('Доля бизнесов с заказами','<h4>Аудитория 1–10 тыс.</h4>'+bars([('С просмотрами',21.2,'#07f'),('Без просмотров',6.2,'#9abce1')],50)+'<h4>Аудитория 10–100 тыс.</h4>'+bars([('С просмотрами',38.1,'#07f'),('Без просмотров',18.9,'#9abce1')],50)) +panel('Сегмент пилота',stat('493','сообщества с активным каталогом, просмотрами товарного контента и аудиторией свыше 1 тыс. до 100 тыс.')+stat('121 из 493','получили хотя бы один заказ за месяц. Остальные 372 уже имеют аудиторию для теста.'),'tint')+'</div><p class="take">Даже при сходном размере аудитории магазины различаются активностью и ассортиментом. Вклад нового сценария проверим случайным распределением бизнесов.</p>'
    choice='<div class="twocol">'+panel('Запускаем первым','<h2>Кабинет продавца</h2><p>Бизнес уже присутствует в VK. Стоимость и результат следующего действия можно измерить на уровне одного сообщества.</p>'+stat('4,8 млн ₽','оценка запуска, включая разработку и аналитику'),'ink')+panel('Что откладываем',''.join(f'<div class="choice"><b>{x}</b><span>{y}</span></div>' for x,y in [('Широкая витрина','Сначала проверим возврат к знакомому товару.'),('Программа с авторами','Даёт охват, но магазину ещё нужно выполнить заказ.'),('Новые продавцы','Привлечение имеет смысл после проверки активации.'),('Субсидии','Скидка затруднит оценку самостоятельного спроса.')]))+'</div><p class="take">У VK есть контекст публикации и диалога с покупателем. Проверяем, помогает ли он довести интерес до оформленного заказа.</p>'
    screens='<div class="prototype">'+panel('01 / Кабинет сообщества','<div class="apphead">Мастерская «Тёплый дом»</div><h3>Подготовьте кружку к продаже</h3><div class="check">✓ Цена и наличие</div><div class="check">✓ Фотография товара</div><div class="pending">Укажите способ получения</div><div class="action">Добавить самовывоз</div>')+panel('02 / Публикация',product()+'<h3>Кружка ручной работы</h3><p>Тёплая глазурь, 300 мл. Можно забрать в мастерской.</p><div class="action">Прикрепить товар</div>')+panel('03 / Покупка','<div class="apphead">Карточка товара</div><h3>Кружка «Песок»</h3>'+stat('1 200 ₽','В наличии · самовывоз')+'<div class="action">Оформить заказ</div><div class="receipt">После подтверждения продавец увидит статус и сможет отметить выдачу.</div>')+'</div><p class="take">Макеты предложения команды. На каждом шаге видны товар, следующее действие и результат для другой стороны.</p>'
    path='<div class="journey">'+''.join(f'<article><small>{i:02d}</small><h3>{x}</h3><p>{y}</p></article>' for i,(x,y) in enumerate([('Подготовить','Новичку предлагаем заполнить одну карточку. Опытный продавец выбирает готовую.'),('Показать','В публикации или клипе товар остаётся связан с историей, которая вызвала интерес.'),('Выполнить','Покупатель видит получение до заказа. Продавец подтверждает выдачу или причину отмены.'),('Вернуть','В Маркете покупатель снова находит сохранённый товар и знакомый магазин.')],1))+'</div><div class="twocol">'+panel('Откуда открывают карточки VK',bars([('Витрины',39.1,'#07f'),('Лента и клипы',18.6,'#49a2ff'),('Главная Маркета',0.21,'#ed389a')],50))+panel('Как проверить роль Маркета','<h3>Повторная покупка за 30 дней</h3><p>Сравним возвраты и заказы теста с контролем. В «Другое» попало 40,2% открытий, поэтому отдельно проверим разметку источников.</p>','tint')+'</div>'
    econ='<div class="twocol">'+panel('Базовый сценарий / млн ₽','<h3>Накопленный денежный поток</h3>'+cash_chart(model)+'<p>6 000 активных бизнесов, 20% увеличивают рекламные расходы на 1 500 ₽ в месяц. Выход на масштаб занимает полгода.</p>')+panel('Три сценария / в месяц на масштабе',stat('−325 тыс. ₽','Осторожный · 2 000 активных бизнесов')+stat('+410 тыс. ₽','Базовый · окупаемость на 17-м месяце')+stat('+2,86 млн ₽','Высокий · 14 000 активных бизнесов'),'tint')+'</div><p class="take">При базовых допущениях операционная безубыточность наступает при 2 963 активных бизнесах. Реальные расходы и дополнительный рекламный доход измеряем в пилоте.</p>'
    pilot='<div class="timeline">'+''.join(f'<div><b>{x}</b><p>{y}</p></div>' for x,y in [('1–2 недели','Интервью, проверка сегмента и определения заказа'),('3–6','Прототип кабинета и проверка событий аналитики'),('7–8','50–100 продавцов: проверяем весь путь до выдачи'),('9–12+','Случайное распределение и 30 дней наблюдения')])+'</div><div class="twocol">'+panel('Что измеряем',stat('Заказы','Главный результат VK: прирост оформленных заказов на назначенный бизнес за 30 дней. Включаем бизнесы с нулём заказов.')+'<p>Группы сравниваем по назначению в тест. Контролируем отмены, жалобы, время исполнения и перенос заказов между каналами.</p>','tint')+panel('Решение о масштабировании',stat('2 476','бизнесов для проверки доли продающих, по 1 238 на группу')+'<p>Расчёт для цели +5 п.п. к доле продающих. Мощность для числа заказов считаем отдельно по дисперсии до запуска. Масштабируем при росте заказов и приемлемой экономике.</p>')+'</div>'
    return [('',cover),('Чекаут подключили 91,9% магазинов с активным каталогом. Заказы есть у 7,2%',why),('Начинаем с магазинов, которые уже показывают товары аудитории',segments),('Первым тестируем кабинет продавца',choice),('Как публикация с товаром превращается в заказ',screens),('Сообщество знакомит с товаром, Маркет возвращает к покупке',path),('В базовом сценарии вложения вернутся на 17-м месяце',econ),('Сначала проверяем путь заказа, затем измеряем прирост продаж',pilot)]

def team():
    return '<div class="teamgrid">'+''.join('<article>'+ (photo(img,n) if img else '<div class="initial">'+initial+'</div>')+f'<h3>{n}</h3></article>' for n,img,initial in [('Егор Чуланов','egor.webp',''),('Екатерина Макаренко','kate.webp',''),('Максим Ширяев','','МШ'),('Анфиса Опарина','','АО')])+'</div><p class="take">Digital Cat$ / Москва / Стратегия на основе аналитики</p>'
